package com.amit.jobagent.matching;import com.amit.jobagent.common.persistence.MutableEntity;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="evaluation_feedback")class EvaluationFeedback extends MutableEntity{@Column(name="evaluation_id",nullable=false,unique=true,updatable=false)UUID evaluationId;@Enumerated(EnumType.STRING)@Column(name="human_label",nullable=false)HumanLabel label;@Column(name="was_recommendation_correct",nullable=false)boolean correct;@Column(length=1000)String notes;protected EvaluationFeedback(){}EvaluationFeedback(UUID id,FeedbackRequest r){evaluationId=id;apply(r);}void apply(FeedbackRequest r){label=r.humanLabel();correct=r.wasRecommendationCorrect();notes=r.notes()==null?null:r.notes().trim();}}
